const escalate = raw.includes('[[EQUIPO]]');
const replyText = raw.split('[[EQUIPO]]').join('').trim();
const wb = $('Webhook').item.json.body;
const from = wb.From;
const nm = parseInt(wb.NumMedia || '0', 10);
const type = wb.MediaContentType0 || '';
const mediaUrl = nm > 0 ? (wb.MediaUrl0 || '') : '';
const kind = type.startsWith('audio') ? 'un audio' : type.startsWith('image') ? 'una foto' : type.startsWith('video') ? 'un video' : 'un archivo';
const customerMessage = (wb.Body || '') + (nm > 0 ? ` [el cliente envió ${kind}]` : '');

const sd = $getWorkflowStaticData('global');
sd.hist = sd.hist || {};
const now = Date.now();
sd.hist[from] = (sd.hist[from] || []).concat([
  { role: 'user', content: customerMessage.trim() || '(mensaje vacío)', t: now },
  { role: 'assistant', content: replyText, t: now }
]).slice(-10);

return [{ json: { replyText, to: from, escalate: escalate || nm > 0, customerMessage: customerMessage.trim(), customerNumber: from, mediaUrl } }];

const rows = $input.all().map(i => i.json);
const lines = rows.filter(r => r['Producto']).map(r => {
  const note = r['Notas'] && !/confirmar|ilegible|aparece a/i.test(r['Notas']) ? ' — ' + r['Notas'] : '';
  return `- ${r['Producto']} (${r['Categoría']}): $${r['Precio (MXN)']} MXN — Disponible hoy: ${r['Disponible hoy (Sí/No)']}${note}`;
});
return [{ json: { priceList: lines.join('\n') } }];

