const sd = $getWorkflowStaticData('global');
sd.hist = sd.hist || {};
const wb = $('Webhook').item.json.body;
const from = wb.From;
const original = wb.Body || '';
const nm = parseInt(wb.NumMedia || '0', 10);
const type = wb.MediaContentType0 || '';
const now = Date.now();
const TTL = 6 * 3600 * 1000;

let body = original;
if (nm > 0) {
  const kind = type.startsWith('audio') ? 'un audio' : type.startsWith('image') ? 'una foto' : type.startsWith('video') ? 'un video' : 'un archivo';
  body = (original ? original + '\n' : '') + `[SISTEMA: el cliente envió ${kind}, que no puedes ver ni escuchar. Responde breve y amable, dile que el equipo lo revisará y que, si puede, también lo escriba. Termina con la marca [[EQUIPO]].]`;
}

for (const k of Object.keys(sd.hist)) {
  sd.hist[k] = sd.hist[k].filter(m => now - m.t < TTL);
  if (sd.hist[k].length === 0) delete sd.hist[k];
}

const past = (sd.hist[from] || []).slice(-8).map(m => ({ role: m.role, content: m.content }));
const all = past.concat([{ role: 'user', content: body || '(mensaje vacío)' }]);
while (all.length && all[0].role !== 'user') all.shift();
const messages = [];
for (const m of all) {
  const last = messages[messages.length - 1];
  if (last && last.role === m.role) last.content += '\n' + m.content;
  else messages.push({ role: m.role, content: m.content });
}
return [{ json: { messages } }];

const rows = $input.all().map(i => i.json);
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Mexico_City' }));
const today = [now.getFullYear(), now.getMonth() + 1, now.getDate()];

function toYMD(v) {
  if (v === undefined || v === null || v === '') return null;
  const s = String(v).trim();
  if (/^\d+(\.\d+)?$/.test(s)) {
    const dt = new Date(Math.round((Number(s) - 25569) * 86400000));
    return [dt.getUTCFullYear(), dt.getUTCMonth() + 1, dt.getUTCDate()];
  }
  let a = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})$/);
  if (a) { let y = +a[3]; if (y < 100) y += 2000; return [y, +a[2], +a[1]]; }
  a = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (a) return [+a[1], +a[2], +a[3]];
  return null;
}
const norm = (k) => k.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
function get(r, name) {
  const k = Object.keys(r).find(x => norm(x) === name);
  return k ? r[k] : '';
}

const todays = rows.filter(r => {
  const d = toYMD(get(r, 'fecha'));
  return d && d[0] === today[0] && d[1] === today[1] && d[2] === today[2] && String(get(r, 'platillo')).trim();
});

const lines = todays.map(r => {
  const sec = String(get(r, 'seccion')).trim();
  const dish = String(get(r, 'platillo')).trim();
  const note = String(get(r, 'notas')).trim();
  const soldOut = String(get(r, 'disponible hoy')).trim().toLowerCase() === 'no';
  return '- ' + (sec ? sec + ': ' : '') + dish + (note ? ' (' + note + ')' : '') + (soldOut ? ' [AGOTADO HOY]' : '');
});

const menuText = lines.length
  ? lines.join('\n')
  : '(No hay menú del día cargado para hoy: no lo inventes, confírmalo con el equipo.)';
return [{ json: { menuText, filasHoy: lines.length } }];

